import numpy as np, base64, json, os
def b64(x):
    x=np.clip(x,-1,1)
    return base64.b64encode((x.astype(np.int32)*int(32000/1)).astype('<i2').tobytes()).decode()
def cyc(n, f):
    t=np.arange(n)/n
    return np.sin(2*np.pi*t)
print(json.dumps([{"name":"sample_create_from_pcm","arguments":{"instrument":1,"sample":0,"encoding":"int16","name":"cyc","pcm":b64(cyc(512,1))}}]))
EOF
python3 work/mk.py > work/b1.json && ft2 batch work/b1.json"}

